/** The seven Eras of V5.1a (canon §1). Hegemony is not an Era: Era VII only opens the Declaration. */
export const AlphaEraSchema = z.enum(['FOUNDATION', 'EXPANSION', 'CONSOLIDATION', 'CIVILIZATION', 'EMPIRES', 'POWERS', 'ASCENSION']);
export type AlphaEra = z.infer<typeof AlphaEraSchema>;
export const ALPHA_ERA_NUMERALS = ['I', 'II', 'III', 'IV', 'V', 'VI', 'VII'] as const;
export const eraNumeral = (era: AlphaEra): string => ALPHA_ERA_NUMERALS[AlphaEraSchema.options.indexOf(era)]!;
export const eraIndex = (era: AlphaEra): number => AlphaEraSchema.options.indexOf(era);
/** Eras pass by the calendar: `roundsPerEra` rounds each, the last Era absorbing any extra rounds. */
export const eraForRound = (round: number, roundsPerEra: number): AlphaEra => AlphaEraSchema.options[Math.min(AlphaEraSchema.options.length - 1, Math.floor((Math.max(1, round) - 1) / Math.max(1, roundsPerEra)))]!;
/** Saved matches from before V5.1a stored the sixth Era as HEGEMONY; it reads as Ascensão. */
export const LegacyAlphaEraSchema = z.preprocess(value => value === 'HEGEMONY' ? 'ASCENSION' : value, AlphaEraSchema);

export const AlphaRoundPhaseSchema = z.enum([
  'WORLD_PULSE',
  'PLANNING',
  'URBAN_ACTIONS',
  'ORDERS_MOVEMENT',
  'DIPLOMACY_TRADE',
  'CONFLICTS',
  'INTEGRATION_MAINTENANCE',
  'END_ROUND',
  /** The Era turn (canon §22): nine steps between the last round of an Era and the first of the next. */
  'ERA_TURN',
]);
export type AlphaRoundPhase = z.infer<typeof AlphaRoundPhaseSchema>;
/** The nine steps of the Era turn (canon §22), in order. */
export const ERA_TURN_STEPS = [
  'Sustento e efeitos de fim de Era', 'Pontuar Ambição', 'Pulso do Mundo', 'Ameaças do Mundo', 'Reforma de Governo',
  'Poder do Líder', 'Manobras e Ambições', 'Próximo patamar da Teia', 'Nova Era',
] as const;


/** The eight resources of V5.1a (canon §3): four materials limited at 15 and four civilizational ones limited at 10. */
export const ALPHA_RESOURCE_KEYS = ['food', 'wood', 'stone', 'metal', 'wealth', 'knowledge', 'influence', 'culture'] as const;
export type AlphaResourceKey = (typeof ALPHA_RESOURCE_KEYS)[number];
export const AlphaResourceTypeSchema = z.enum(['FOOD', 'WOOD', 'STONE', 'METAL', 'WEALTH', 'KNOWLEDGE', 'INFLUENCE', 'CULTURE']);
export type AlphaResourceType = z.infer<typeof AlphaResourceTypeSchema>;
export const AlphaResourcePoolSchema = z.strictObject({
  food: N,
  wood: N,
  stone: N,
  metal: N,
  wealth: N,
  knowledge: N,
  influence: N,
  /** Cultura is a resource since V5.1a; matches saved before it read as 0. */
  culture: N.default(0),
});
export type AlphaResourcePool = z.infer<typeof AlphaResourcePoolSchema>;
export const emptyAlphaResourcePool = (): AlphaResourcePool => ({ food: 0, wood: 0, stone: 0, metal: 0, wealth: 0, knowledge: 0, influence: 0, culture: 0 });
export const legacyToAlphaResources = (pool: ResourcePool): AlphaResourcePool => ({
  food: pool.food,
  wood: Math.ceil(pool.materials / 2),
  stone: Math.floor(pool.materials / 2),
  metal: 0,
  wealth: pool.wealth,
  knowledge: pool.knowledge,
  influence: pool.influence,
  culture: 0,
});
/** What a gain written in a legacy resource credits in the seven resources (legacy "materials" splits as above). */
export const alphaGainOf = (resource: keyof ResourcePool, amount: number): AlphaResourcePool =>
  legacyToAlphaResources({ food: 0, materials: 0, wealth: 0, knowledge: 0, influence: 0, [resource]: amount });
export const alphaToLegacyResources = (pool: AlphaResourcePool): ResourcePool => ResourcePoolSchema.parse({
  food: pool.food,
  materials: pool.wood + pool.stone + pool.metal,
  wealth: pool.wealth,
  knowledge: pool.knowledge,
  influence: pool.influence,
});

